export const WINNING_LINES = [
  [0, 1, 2],
  [3, 4, 5],
  [6, 7, 8],
  [0, 3, 6],
  [1, 4, 7],
  [2, 5, 8],
  [0, 4, 8],
  [2, 4, 6],
];

export const SYMBOLS = {
  X: 'X',
  O: 'O',
};

export const GAME_MODES = {
  PVP: 'PVP',
  CPU: 'CPU',
};

export const GAME_STATUS = {
  IN_PROGRESS: 'IN_PROGRESS',
  WIN: 'WIN',
  DRAW: 'DRAW',
};

import { WINNING_LINES, GAME_STATUS, SYMBOLS } from '../constants/gameConstants.js';

/**
 * Evaluates the current board state.
 * @param {Array<string|null>} board - 9-element array of 'X', 'O', or null
 * @returns {{ status: string, winner: string|null, winningLine: number[]|null }}
 */
export function checkGameResult(board) {
  if (!Array.isArray(board) || board.length !== 9) {
    throw new Error('Board must be a 9-element array');
  }

  for (const line of WINNING_LINES) {
    const [a, b, c] = line;
    if (
      board[a] !== null &&
      board[a] !== undefined &&
      board[a] === board[b] &&
      board[a] === board[c]
    ) {
      return {
        status: GAME_STATUS.WIN,
        winner: board[a],
        winningLine: line,
      };
    }
  }

  const isBoardFull = board.every((cell) => cell !== null && cell !== undefined);
  if (isBoardFull) {
    return {
      status: GAME_STATUS.DRAW,
      winner: null,
      winningLine: null,
    };
  }

  return {
    status: GAME_STATUS.IN_PROGRESS,
    winner: null,
    winningLine: null,
  };
}

/**
 * Returns true if the given symbol has won on the board.
 * @param {Array<string|null>} board
 * @param {string} symbol
 * @returns {boolean}
 */
export function hasWon(board, symbol) {
  return WINNING_LINES.some(
    ([a, b, c]) => board[a] === symbol && board[b] === symbol && board[c] === symbol
  );
}

/**
 * Returns available (empty) cell indices.
 * @param {Array<string|null>} board
 * @returns {number[]}
 */
export function getAvailableMoves(board) {
  return board.reduce((moves, cell, index) => {
    if (cell === null || cell === undefined) {
      moves.push(index);
    }
    return moves;
  }, []);
}

import { SYMBOLS, GAME_STATUS } from '../constants/gameConstants.js';
import { checkGameResult, getAvailableMoves } from './winDetection.js';

const SCORES = {
  [SYMBOLS.X]: -10,
  [SYMBOLS.O]: 10,
  DRAW: 0,
};

/**
 * Minimax recursive evaluation.
 * CPU always plays as 'O' (maximizing), human plays as 'X' (minimizing).
 * @param {Array<string|null>} board
 * @param {boolean} isMaximizing
 * @param {number} depth
 * @returns {number}
 */
function minimax(board, isMaximizing, depth) {
  const result = checkGameResult(board);

  if (result.status === GAME_STATUS.WIN) {
    const score = result.winner === SYMBOLS.O ? 10 - depth : depth - 10;
    return score;
  }

  if (result.status === GAME_STATUS.DRAW) {
    return SCORES.DRAW;
  }

  const availableMoves = getAvailableMoves(board);

  if (isMaximizing) {
    let bestScore = -Infinity;
    for (const move of availableMoves) {
      const newBoard = [...board];
      newBoard[move] = SYMBOLS.O;
      const score = minimax(newBoard, false, depth + 1);
      bestScore = Math.max(bestScore, score);
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (const move of availableMoves) {
      const newBoard = [...board];
      newBoard[move] = SYMBOLS.X;
      const score = minimax(newBoard, true, depth + 1);
      bestScore = Math.min(bestScore, score);
    }
    return bestScore;
  }
}

/**
 * Returns the best cell index for the CPU player (O).
 * @param {Array<string|null>} board - 9-element board array
 * @returns {number} optimal cell index
 */
export function getBestMove(board) {
  const availableMoves = getAvailableMoves(board);

  if (availableMoves.length === 0) {
    throw new Error('No available moves on the board');
  }

  if (availableMoves.length === 9) {
    const corners = [0, 2, 6, 8];
    return corners[Math.floor(Math.random() * corners.length)];
  }

  let bestScore = -Infinity;
  let bestMove = availableMoves[0];

  for (const move of availableMoves) {
    const newBoard = [...board];
    newBoard[move] = SYMBOLS.O;
    const score = minimax(newBoard, false, 0);
    if (score > bestScore) {
      bestScore = score;
      bestMove = move;
    }
  }

  return bestMove;
}

import { createSlice } from '@reduxjs/toolkit';
import { SYMBOLS, GAME_MODES, GAME_STATUS } from '../constants/gameConstants.js';

const EMPTY_BOARD = Array(9).fill(null);

const initialState = {
  board: [...EMPTY_BOARD],
  currentTurn: SYMBOLS.X,
  gameStatus: GAME_STATUS.IN_PROGRESS,
  winner: null,
  winningLine: null,
  selectedMode: null,
  scoreboard: {
    xWins: 0,
    oWins: 0,
    draws: 0,
  },
};

const gameSlice = createSlice({
  name: 'game',
  initialState,
  reducers: {
    setMode(state, action) {
      const mode = action.payload;
      if (!Object.values(GAME_MODES).includes(mode)) {
        return;
      }
      state.selectedMode = mode;
      state.board = [...EMPTY_BOARD];
      state.currentTurn = SYMBOLS.X;
      state.gameStatus = GAME_STATUS.IN_PROGRESS;
      state.winner = null;
      state.winningLine = null;
    },

    placeSymbol(state, action) {
      const { index, symbol, nextTurn, status, winner, winningLine } = action.payload;

      if (
        index < 0 ||
        index > 8 ||
        state.board[index] !== null ||
        state.gameStatus !== GAME_STATUS.IN_PROGRESS
      ) {
        return;
      }

      state.board[index] = symbol;
      state.currentTurn = nextTurn;
      state.gameStatus = status;
      state.winner = winner !== undefined ? winner : null;
      state.winningLine = winningLine !== undefined ? winningLine : null;
    },

    resetBoard(state) {
      state.board = [...EMPTY_BOARD];
      state.currentTurn = SYMBOLS.X;
      state.gameStatus = GAME_STATUS.IN_PROGRESS;
      state.winner = null;
      state.winningLine = null;
    },

    updateScoreboard(state, action) {
      const { result } = action.payload;
      if (result === SYMBOLS.X) {
        state.scoreboard.xWins += 1;
      } else if (result === SYMBOLS.O) {
        state.scoreboard.oWins += 1;
      } else if (result === GAME_STATUS.DRAW) {
        state.scoreboard.draws += 1;
      }
    },

    resetAll(state) {
      Object.assign(state, initialState);
      state.board = [...EMPTY_BOARD];
      state.scoreboard = { xWins: 0, oWins: 0, draws: 0 };
    },
  },
});

export const { setMode, placeSymbol, resetBoard, updateScoreboard, resetAll } = gameSlice.actions;

export const selectBoard = (state) => state.game.board;
export const selectCurrentTurn = (state) => state.game.currentTurn;
export const selectGameStatus = (state) => state.game.gameStatus;
export const selectWinner = (state) => state.game.winner;
export const selectWinningLine = (state) => state.game.winningLine;
export const selectSelectedMode = (state) => state.game.selectedMode;
export const selectScoreboard = (state) => state.game.scoreboard;

export default gameSlice.reducer;

import { configureStore } from '@reduxjs/toolkit';
import gameReducer from './gameSlice.js';

const STORAGE_KEY = 'tictactoe_scoreboard';

function loadScoreboardFromStorage() {
  try {
    const serialized = localStorage.getItem(STORAGE_KEY);
    if (serialized === null) return undefined;
    return JSON.parse(serialized);
  } catch {
    return undefined;
  }
}

function saveScoreboardToStorage(scoreboard) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(scoreboard));
  } catch {
    // Storage unavailable — silently ignore
  }
}

const persistedScoreboard = loadScoreboardFromStorage();

const preloadedState = persistedScoreboard
  ? { game: { scoreboard: persistedScoreboard } }
  : undefined;

export const store = configureStore({
  reducer: {
    game: gameReducer,
  },
  preloadedState,
});

store.subscribe(() => {
  const state = store.getState();
  saveScoreboardToStorage(state.game.scoreboard);
});

export default store;

import { useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import {
  placeSymbol,
  updateScoreboard,
  selectBoard,
  selectCurrentTurn,
  selectGameStatus,
  selectSelectedMode,
} from '../store/gameSlice.js';
import { checkGameResult } from '../engine/winDetection.js';
import { getBestMove } from '../engine/minimax.js';
import { SYMBOLS, GAME_MODES, GAME_STATUS } from '../constants/gameConstants.js';

export function useGameState() {
  const dispatch = useDispatch();
  const board = useSelector(selectBoard);
  const currentTurn = useSelector(selectCurrentTurn);
  const gameStatus = useSelector(selectGameStatus);
  const selectedMode = useSelector(selectSelectedMode);

  const resolveNextState = useCallback(
    (newBoard, symbol) => {
      const result = checkGameResult(newBoard);
      const nextTurn = symbol === SYMBOLS.X ? SYMBOLS.O : SYMBOLS.X;

      return {
        status: result.status,
        winner: result.winner,
        winningLine: result.winningLine,
        nextTurn: result.status === GAME_STATUS.IN_PROGRESS ? nextTurn : currentTurn,
      };
    },
    [currentTurn]
  );

  const dispatchMoveAndCheckResult = useCallback(
    (index, symbol, boardSnapshot) => {
      const newBoard = [...boardSnapshot];
      newBoard[index] = symbol;

      const { status, winner, winningLine, nextTurn } = resolveNextState(newBoard, symbol);

      dispatch(
        placeSymbol({
          index,
          symbol,
          nextTurn,
          status,
          winner,
          winningLine,
        })
      );

      if (status === GAME_STATUS.WIN) {
        dispatch(updateScoreboard({ result: winner }));
      } else if (status === GAME_STATUS.DRAW) {
        dispatch(updateScoreboard({ result: GAME_STATUS.DRAW }));
      }

      return { status, newBoard };
    },
    [dispatch, resolveNextState]
  );

  const handleCellClick = useCallback(
    (index) => {
      if (
        gameStatus !== GAME_STATUS.IN_PROGRESS ||
        board[index] !== null ||
        !selectedMode
      ) {
        return;
      }

      if (selectedMode === GAME_MODES.CPU && currentTurn === SYMBOLS.O) {
        return;
      }

      const { status, newBoard } = dispatchMoveAndCheckResult(index, currentTurn, board);

      if (
        status === GAME_STATUS.IN_PROGRESS &&
        selectedMode === GAME_MODES.CPU
      ) {
        setTimeout(() => {
          const boardAfterHuman = [...newBoard];
          const cpuIndex = getBestMove(boardAfterHuman);
          dispatchMoveAndCheckResult(cpuIndex, SYMBOLS.O, boardAfterHuman);
        }, 300);
      }
    },
    [board, currentTurn, gameStatus, selectedMode, dispatchMoveAndCheckResult]
  );

  return { handleCellClick };
}

import React from 'react';

const SYMBOL_STYLES = {
  X: { color: '#e74c3c' },
  O: { color: '#3498db' },
};

const cellStyle = {
  width: '100px',
  height: '100px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: '2.5rem',
  fontWeight: 'bold',
  border: '2px solid #2c3e50',
  cursor: 'pointer',
  backgroundColor: '#ecf0f1',
  transition: 'background-color 0.2s ease',
  userSelect: 'none',
};

const occupiedStyle = {
  ...cellStyle,
  cursor: 'not-allowed',
  backgroundColor: '#dfe6e9',
};

function Cell({ symbol, onClick, index, isWinningCell }) {
  const isOccupied = symbol !== null && symbol !== undefined;

  const handleClick = () => {
    if (!isOccupied) {
      onClick(index);
    }
  };

  const computedStyle = {
    ...(isOccupied ? occupiedStyle : cellStyle),
    ...(isWinningCell ? { backgroundColor: '#f9ca24' } : {}),
    ...(symbol ? SYMBOL_STYLES[symbol] : {}),
  };

  return (
    <div
      style={computedStyle}
      onClick={handleClick}
      role="button"
      aria-label={`Cell ${index + 1}: ${symbol || 'empty'}`}
      data-testid={`cell-${index}`}
    >
      {symbol || ''}
    </div>
  );
}

export default Cell;

import React from 'react';
import { useSelector } from 'react-redux';
import Cell from './Cell.jsx';
import { useGameState } from '../hooks/useGameState.js';
import { selectBoard, selectWinningLine } from '../store/gameSlice.js';

const boardStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(3, 100px)',
  gridTemplateRows: 'repeat(3, 100px)',
  gap: '4px',
  margin: '20px auto',
  width: 'fit-content',
};

function Board() {
  const board = useSelector(selectBoard);
  const winningLine = useSelector(selectWinningLine);
  const { handleCellClick } = useGameState();

  return (
    <div style={boardStyle} data-testid="board">
      {board.map((symbol, index) => (
        <Cell
          key={index}
          index={index}
          symbol={symbol}
          onClick={handleCellClick}
          isWinningCell={winningLine !== null && winningLine.includes(index)}
        />
      ))}
    </div>
  );
}

export default Board;

import React from 'react';
import { useSelector } from 'react-redux';
import {
  selectGameStatus,
  selectCurrentTurn,
  selectWinner,
} from '../store/gameSlice.js';
import { GAME_STATUS } from '../constants/gameConstants.js';

const containerStyle = {
  textAlign: 'center',
  fontSize: '1.4rem',
  fontWeight: '600',
  margin: '16px 0',
  minHeight: '2rem',
  color: '#2c3e50',
};

function GameStatus() {
  const gameStatus = useSelector(selectGameStatus);
  const currentTurn = useSelector(selectCurrentTurn);
  const winner = useSelector(selectWinner);

  let message = '';

  if (gameStatus === GAME_STATUS.WIN) {
    message = `🎉 Player ${winner} wins!`;
  } else if (gameStatus === GAME_STATUS.DRAW) {
    message = "🤝 It's a draw!";
  } else {
    message = `Player ${currentTurn}'s turn`;
  }

  return (
    <div style={containerStyle} data-testid="game-status">
      {message}
    </div>
  );
}

