import { describe, it, expect } from 'vitest';
import { checkGameResult, hasWon, getAvailableMoves } from '../../src/engine/winDetection.js';
import { GAME_STATUS, SYMBOLS } from '../../src/constants/gameConstants.js';

describe('checkGameResult', () => {
  it('should return IN_PROGRESS for an empty board', () => {
    const board = Array(9).fill(null);
    const result = checkGameResult(board);
    expect(result.status).toBe(GAME_STATUS.IN_PROGRESS);
    expect(result.winner).toBeNull();
    expect(result.winningLine).toBeNull();
  });

  it('should detect X wins on top row [0,1,2]', () => {
    const board = ['X', 'X', 'X', null, null, null, null, null, null];
    const result = checkGameResult(board);
    expect(result.status).toBe(GAME_STATUS.WIN);
    expect(result.winner).toBe(SYMBOLS.X);
    expect(result.winningLine).toEqual([0, 1, 2]);
  });

  it('should detect X wins on middle row [3,4,5]', () => {
    const board = [null, null, null, 'X', 'X', 'X', null, null, null];
    const result = checkGameResult(board);
    expect(result.status).toBe(GAME_STATUS.WIN);
    expect(result.winner).toBe(SYMBOLS.X);
    expect(result.winningLine).toEqual([3, 4, 5]);
  });

  it('should detect X wins on bottom row [6,7,8]', () => {
    const board = [null, null, null, null, null, null, 'X', 'X', 'X'];
    const result = checkGameResult(board);
    expect(result.status).toBe(GAME_STATUS.WIN);
    expect(result.winner).toBe(SYMBOLS.X);
    expect(result.winningLine).toEqual([6, 7, 8]);
  });

  it('should detect O wins on left column [0,3,6]', () => {
    const board = ['O', null, null, 'O', null, null, 'O', null, null];
    const result = checkGameResult(board);
    expect(result.status).toBe(GAME_STATUS.WIN);
