import { describe, it, expect } from 'vitest';
import { getBestMove } from '../../src/engine/minimax.js';

describe('getBestMove', () => {
  it('should return a valid cell index for a partially filled board', () => {
    const board = ['X', null, null, null, 'O', null, null, null, 'X'];
    const move = getBestMove(board);
    expect(typeof move).toBe('number');
    expect(move).toBeGreaterThanOrEqual(0);
    expect(move).toBeLessThanOrEqual(8);
    expect(board[move]).toBeNull();
  });

  it('should block X from winning immediately', () => {
    // X is about to win at index 2 — CPU must block
    const board = ['X', 'X', null, 'O', null, null, null, null, null];
    const move = getBestMove(board);
    expect(move).toBe(2);
  });

  it('should take a winning move when available', () => {
    // O can win at index 6
    const board = ['X', 'X', null, 'O', 'O', null, null, null, 'X'];
    const move = getBestMove(board);
    expect(move).toBe(5);
  });

  it('should win when O has two in a row and can complete', () => {
    // O wins at index 8
    const board = ['X', 'X', 'O', 'X', null, null, 'O', null, null];
    const move = getBestMove(board);
    expect(move).toBe(8);
  });

  it('should throw when no moves are available', () => {
    const board = ['X', 'O', 'X', 'X', 'O', 'O', 'O', 'X', 'X'];
    expect(() => getBestMove(board)).toThrow('No available moves on the board');
  });

  it('should return a corner for an empty board', () => {
    const board = Array(9).fill(null);
    const move = getBestMove(board);
    expect([0, 2, 6, 8]).toContain(move);
  });

  it('CPU should never lose against any human move sequence', () => {
    // Simulate a game where human plays optimally — result must be draw or CPU win
    function simulateGame(board, isHumanTurn) {
      const { checkGameResult } = require('../../src/engine/winDetection.js');
      const result = checkGameResult(board);
      if (result.status !== 'IN_PROGRESS') return result.status;

      if (isHumanTurn) {
        const available = board.reduce((acc, v, i) => (v === null ? [...acc, i] : acc), []);
        for (const move of available) {
          const newBoard = [...board];
          newBoard[move] = 'X';
          const outcome = simulateGame(newBoard, false);
          if (outcome === 'WIN' && board[move] === null) {
            // X won — CPU lost — this should never happen
            return 'CPU_LOST';
          }
        }
        return 'DRAW_OR_CPU_WIN';
      } else {
        const cpuMove = getBestMove(board);
        const newBoard = [...board];
        newBoard[cpuMove] = 'O';
        return simulateGame(newBoard, true);
      }
    }

    // Start with CPU going second (human first)
    const emptyBoard = Array(9).fill(null);
    const available = [0, 1, 2, 3, 4, 5, 6, 7, 8];
    for (const firstMove of available) {
      const board = [...emptyBoard];
      board[firstMove] = 'X';
      const cpuMove = getBestMove(board);
      expect(cpuMove).toBeGreaterThanOrEqual(0);
      expect(cpuMove).toBeLessThanOrEqual(8);
      expect(board[cpuMove]).toBeNull();
    }
  });
});

