import React from 'react';
import { describe, it, expect } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { Provider } from 'react-redux';
import { configureStore } from '@reduxjs/toolkit';
import Board from '../../src/components/Board.jsx';
import gameReducer from '../../src/store/gameSlice.js';
import { GAME_MODES, GAME_STATUS } from '../../src/constants/gameConstants.js';

function createTestStore(preloadedState = {}) {
  return configureStore({
    reducer: { game: gameReducer },
    preloadedState,
  });
}

function renderWithStore(component, store) {
  return render(<Provider store={store}>{component}</Provider>);
}

const defaultGameState = {
  board: Array(9).fill(null),
  currentTurn: 'X',
  gameStatus: GAME_STATUS.IN_PROGRESS,
  winner: null,
  winningLine: null,
  selectedMode: GAME_MODES.PVP,
  scoreboard: { xWins: 0, oWins: 0, draws: 0 },
};

describe('Board', () => {
  it('should render 9 cells', () => {
    const store = createTestStore({ game: defaultGameState });
    renderWithStore(<Board />, store);

    const cells = screen.getAllByRole('button');
    expect(cells).toHaveLength(9);
  });

  it('should display board symbols correctly', () => {
    const store = createTestStore({
      game: {
        ...defaultGameState,
        board: ['X', 'O', null, null, null, null, null, null, null],
      },
    });
    renderWithStore(<Board />, store);

    expect(screen.getByTestId('cell-0')).toHaveTextContent('X');
    expect(screen.getByTestId('cell-1')).toHaveTextContent('O');
    expect(screen.getByTestId('cell-2')).toHaveTextContent('');
  });

  it('should dispatch placeSymbol when an empty cell is clicked in PVP mode', () => {
    const store = createTestStore({ game: defaultGameState });
    renderWithStore(<Board />, store);

    fireEvent.click(screen.getByTestId('cell-4'));

    const state = store.getState();
    expect(state.game.board[4]).toBe('X');
  });

  it('should not overwrite an occupied cell', () => {
    const store = createTestStore({
      game: {
        ...defaultGameState,
        board: ['X', null, null, null, null, null, null, null, null],
        currentTurn: 'O',
      },
    });
    renderWithStore(<Board />, store);

    fireEvent.click(screen.getByTestId('cell-0'));

    const state = store.getState();
    expect(state.game.board[0]).toBe('X');
  });

  it('should not allow moves when game is won', () => {
    const store = createTestStore({
      game: {
        ...defaultGameState,
        board: ['X', 'X', 'X', 'O', 'O', null, null, null, null],
        gameStatus: GAME_STATUS.WIN,
        winner: 'X',
        winningLine: [0, 1, 2],
      },
    });
    renderWithStore(<Board />, store);

    fireEvent.click(screen.getByTestId('cell-5'));

    const state = store.getState();
    expect(state.game.board[5]).toBeNull();
  });
});
